import type { ExerciseDef } from '../domain/types';
import rows from './exercises.json';

/** Bank rows. `stretching` exists only on stretches, so search can rank them last. */
type BankRow = ExerciseDef & { stretching?: boolean };

/** Generated by scripts/build-exercises.mjs. Strength rows come first. */
export const EXERCISES: ExerciseDef[] = rows as BankRow[];

const DEFAULT_LIMIT = 50;

/**
 * Lifter words, as normalised text. Alternatives run from the lift people usually
 * mean to the broadest match, because a variant's position sets its rank.
 */
const ALIASES: [phrase: string, alternatives: string[]][] = [
  ['db', ['dumbbell']],
  ['bb', ['barbell']],
  ['kb', ['kettlebell']],
  ['ohp', ['overhead press', 'standing military press', 'barbell shoulder press', 'shoulder press']],
  ['rdl', ['romanian deadlift', 'stiff legged deadlift']],
  ['bench', ['barbell bench press medium grip', 'bench press', 'bench']],
  ['squat', ['barbell squat', 'squat']],
  ['deadlift', ['barbell deadlift', 'deadlift']],
  ['pulldown', ['wide grip lat pulldown', 'lat pulldown', 'pulldown']],
  ['pullup', ['pullup', 'chinup']],
  ['chin', ['chinup', 'chin']],
  ['dip', ['dip tricep version', 'dip chest version', 'dip']],
  ['shoulder press', ['barbell shoulder press', 'dumbbell shoulder press', 'shoulder press']],
  ['barbell row', ['bent over barbell row', 'barbell row']],
  ['dumbbell row', ['one arm dumbbell row', 'dumbbell row']],
  ['hip thrust', ['barbell hip thrust', 'hip thrust']],
  ['lateral raise', ['side lateral raise', 'lateral raise']],
  ['skullcrusher', ['ez bar skullcrusher', 'skullcrusher', 'lying tricep press']],
  ['dumbbell lateral raise', ['side lateral raise', 'dumbbell lateral raise']],
  ['cable fly', ['cable crossover', 'cable fly']],
  ['machine chest press', ['machine bench press', 'leverage chest press']],
  ['machine row', ['leverage iso row', 'leverage high row']],
  ['chest supported row', ['dumbbell incline row', 'lying t bar row']],
  ['reverse pec deck', ['reverse machine fly']],
  ['hip abduction', ['thigh abductor', 'hip abduction']],
  ['hip adduction', ['thigh adductor', 'hip adduction']],
  ['nordic', ['natural glute ham raise', 'nordic']],
  ['ab wheel', ['ab roller', 'ab wheel']],
];

function singular(word: string): string {
  if (/^fl(y|ye|yes|ies)$/.test(word)) return 'fly';
  if (word === 'calves') return 'calf';
  if (word.length < 4 || /(ss|us|is)$/.test(word)) return word;
  if (/(ss|ch|sh|x)es$/.test(word)) return word.slice(0, -2);
  return word.endsWith('s') ? word.slice(0, -1) : word;
}

/** Lower case, no punctuation, singular words, and one spelling of split compounds. */
function normalise(text: string): string {
  return text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .map(singular)
    .join(' ')
    .replace(/\b(pull|chin|push|sit|step) ups?\b/g, '$1up')
    .replace(/\b(pull|push) down\b/g, '$1down')
    .replace(/\bskull crusher\b/g, 'skullcrusher')
    .replace(/\bdead lift\b/g, 'deadlift');
}

function replacePhrase(text: string, phrase: string, replacement: string): string {
  return ` ${text} `.replace(` ${phrase} `, ` ${replacement} `).trim();
}

/** The query with each alias swapped in, best first, ending with the literal query. */
function variants(query: string): string[] {
  let results = [query];
  for (const [phrase, alternatives] of ALIASES) {
    if (!` ${query} `.includes(` ${phrase} `)) continue;
    results = results.flatMap((text) =>
      alternatives.map((alternative) => replacePhrase(text, phrase, alternative)),
    );
  }
  // "Hack Squat Machine" is logged as "Hack Squat": bank names often leave the machine out.
  const withoutMachine = results.map((text) => replacePhrase(text, 'machine', '').replace(/ +/g, ' '));
  return [...new Set([...results, ...withoutMachine, query])].filter(Boolean);
}

const NO_MATCH = Number.POSITIVE_INFINITY;
const PARTIAL_MATCH = 1_000;
const STRETCHING = 1_000_000;

/** 0 exact, 1 prefix, 2 every word whole, 3 every word begins a name word. */
function matchTier(name: string, nameWords: string[], variant: string): number {
  if (name === variant) return 0;
  if (name.startsWith(variant)) return 1;
  const words = variant.split(' ');
  if (words.every((word) => nameWords.includes(word))) return 2;
  if (words.every((word) => nameWords.some((nameWord) => nameWord.startsWith(word)))) return 3;
  return NO_MATCH;
}

function rank(exercise: BankRow, query: string, queryVariants: string[]): number {
  const name = normalise(exercise.name);
  const nameWords = name.split(' ');
  let best = NO_MATCH;
  queryVariants.forEach((variant, position) => {
    const tier = matchTier(name, nameWords, variant);
    if (tier === NO_MATCH) return;
    // Exact names beat all partial matches; within each band, earlier variants win.
    const score = tier === 0 ? position : PARTIAL_MATCH + position * 4 + tier;
    best = Math.min(best, name === query ? -1 : score);
  });
  // Stretches sit after every strength match, however well they match.
  return best === NO_MATCH || !exercise.stretching ? best : best + STRETCHING;
}

/**
 * Finds exercises whose names hold every query word. Takes the list as an argument
 * so the caller can include custom exercises.
 */
export function searchExercises(
  query: string,
  exercises: ExerciseDef[],
  limit = DEFAULT_LIMIT,
): ExerciseDef[] {
  const normalised = normalise(query);
  if (!normalised) return exercises.slice(0, limit);
  const queryVariants = variants(normalised);
  return exercises
    .map((exercise) => ({ exercise, score: rank(exercise, normalised, queryVariants) }))
    .filter(({ score }) => score !== NO_MATCH)
    .sort((a, b) => a.score - b.score) // stable, so ties keep the list's own order
    .slice(0, limit)
    .map(({ exercise }) => exercise);
}
